from app.core.constants import REQUEST_ID_HEADER

PROBLEM_MEDIA_TYPE = "application/problem+json"


def _assert_problem_shape(body: dict[str, object], status_code: int) -> None:
    assert body["status"] == status_code
    assert isinstance(body["title"], str)
    assert isinstance(body["type"], str)


async def test_missing_token_is_problem_json_with_www_authenticate(
    client: AsyncClient,
) -> None:
    r = await client.get("/api/v1/users/me")
    assert r.status_code == 401
    assert r.headers["content-type"].startswith(PROBLEM_MEDIA_TYPE)
    assert r.headers["www-authenticate"] == "Bearer"
    _assert_problem_shape(r.json(), 401)


