async def test_unhandled_exception_is_problem_json_500(app: FastAPI) -> None:
    async def boom() -> None:
        raise RuntimeError("intentional test failure")

    app.add_api_route("/boom", boom)

    transport = ASGITransport(app=app, raise_app_exceptions=False)
    async with AsyncClient(transport=transport, base_url="http://test") as client:
        r = await client.get("/boom")

    assert r.status_code == 500
    assert r.headers["content-type"].startswith(PROBLEM_MEDIA_TYPE)
    body = r.json()
    _assert_problem_shape(body, 500)
    # No internals leak into the response body.
    assert "intentional test failure" not in r.text
    # The correlation header is present even on the catch-all path.
    assert r.headers.get(REQUEST_ID_HEADER)


async def test_valid_inbound_request_id_is_echoed(client: AsyncClient) -> None:
    r = await client.get("/api/v1/health", headers={REQUEST_ID_HEADER: "trace-42"})
    assert r.headers[REQUEST_ID_HEADER] == "trace-42"


async def test_invalid_inbound_request_id_is_replaced(client: AsyncClient) -> None:
    hostile = "x" * 100 + "\n{}"
    r = await client.get("/api/v1/health", headers={REQUEST_ID_HEADER: hostile})
    echoed = r.headers[REQUEST_ID_HEADER]
    assert echoed != hostile
    assert len(echoed) == 36  # replacement is a generated UUID


async def test_access_log_event_carries_request_id(
    client: AsyncClient, caplog: pytest.LogCaptureFixture
) -> None:
    # The structlog→stdlib bridge makes access events visible to caplog.
    with caplog.at_level(logging.INFO, logger="app.api.middleware"):
        await client.get("/api/v1/health", headers={REQUEST_ID_HEADER: "log-test"})
    messages = [
        record.getMessage()
        for record in caplog.records
        if record.name == "app.api.middleware"
    ]
    assert any(
        "http.request" in message and "log-test" in message for message in messages
    )
